"""Explicit renderer-visible variants for every Design Genome component.

The dictionaries in this module are intentionally keyed by component ID.  A
variant is never selected from registry position, ID text, hashing or a seed.
"""

from __future__ import annotations

from ...models import StructuralVariantSpec


def _v(
    variant_id: str,
    design_intent: str,
    flow: str,
    anchor: str,
    frame: str,
    collapse: str,
    priority: str,
    focus: str,
    *,
    desktop: dict | None = None,
    mobile: dict | None = None,
    media: dict | None = None,
    content: dict | None = None,
    behavior: dict | None = None,
) -> StructuralVariantSpec:
    return StructuralVariantSpec(
        variant_id=variant_id,
        design_intent=design_intent,
        flow_direction=flow,
        alignment_anchor=anchor,
        frame_behavior=frame,
        collapse_strategy=collapse,
        priority_anchor=priority,
        focus_progression=focus,
        desktop_overrides=desktop or {},
        mobile_overrides=mobile or {},
        media_overrides=media or {},
        content_overrides=content or {},
        behavior_overrides=behavior or {},
    )


